 <?php if($complete): ?><div class="grading-finished-date"><span>Tuntas pada</span><strong><?= e(formatTanggalIndo($assignment['completed_at']??$assignment['batas_pengumpulan'])) ?>, <?= e(date('H:i',strtotime($assignment['completed_at']??$assignment['batas_pengumpulan']))) ?> WIB</strong></div>
 <?php else: ?><div class="grading-progress"><div><span><i class="status-dot"></i> <?= $remaining ?> Berkas <?= $closed?'Belum Dikoreksi':'Masuk Baru' ?></span><strong><?= $closed?$percent.'%':((int)$assignment['graded'].'/'.(int)$assignment['total'].' Selesai') ?></strong></div><div class="ui-progress"><span style="width:<?= $percent ?>%"></span></div><small><?= $closed?(int)$assignment['graded'].' berkas sudah tuntas diperiksa':'Belum final (siswa masih mengunggah)' ?></small></div><?php endif; ?>
 <div class="grading-actions"><a class="ui-button <?= $complete?'white':($closed?($urgent?'primary':'muted-primary'):'soft') ?>" href="<?= uiQuery(['tugas_id'=>$assignment['id'],'status'=>'all']) ?>"><?= uiIcon($complete?'table':($urgent?'grade-review':'edit'),18) ?> <?= $complete?'Lihat Rekap Nilai':($closed?($urgent?'Mulai Koreksi & Input Nilai':'Lanjutkan Koreksi'):'Koreksi '.$remaining.' Berkas') ?></a><?php if(!$complete): ?><a class="ui-button soft small" href="download.php?type=arsip&id=<?= (int)$assignment['id'] ?>"><?= uiIcon($urgent?'folder':'cloud-download',16) ?> <?= $urgent?'Unduh Berkas (ZIP)':'Unduh Berkas' ?></a><?php endif; ?></div>
